import{_ as s,a0 as i,w as p,s as l,ao as C,I as a,x as t,a1 as o,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"LinuxCon: 服务器操作系统的转型 | LCTT x X-CMD","titleTemplate":false,"description":"LinuxCon: 服务器操作系统的转型 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LinuxCon: 服务器操作系统的转型 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LinuxCon: 服务器操作系统的转型 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150819 Linuxcon--The Changing Role of the Server OS","title":"LinuxCon: 服务器操作系统的转型","tag":"201509","desc":""},"relativePath":"201509/20150819 Linuxcon--The Changing Role of the Server OS.md","filePath":"[post].md"}'),u={name:"201509/20150819 Linuxcon--The Changing Role of the Server OS.md"};function x(m,e,h,d,f,T){const r=i("Link");return p(),l("div",null,[e[13]||(e[13]=C('<h1 id="linuxcon-服务器操作系统的转型" tabindex="-1">LinuxCon: 服务器操作系统的转型 <a class="header-anchor" href="#linuxcon-服务器操作系统的转型" aria-label="Permalink to “LinuxCon: 服务器操作系统的转型”">​</a></h1><p>西雅图报道。容器迟早要改变世界，以及改变操作系统的角色。这是 Wim Coekaerts 带来的 LinuxCon 演讲主题，Coekaerts 是 Oracle 公司 Linux 与虚拟化工程的高级副总裁。</p><p><img src="http://www.serverwatch.com/imagesvr_ce/6421/wim-200x150.jpg" alt=""></p><p>Coekaerts 在开始演讲的时候拿出一张关于“桌面之年”的幻灯片，引发了现场观众的一片笑声。之后他说 2015 年很明显是容器之年，更是应用之年，应用才是容器的关键。</p><p>“你需要操作系统做什么事情？”，Coekaerts 回答现场观众：“只需一件事：运行一个应用。操作系统负责管理硬件和资源，来让你的应用运行起来。”</p><p>Coakaerts 补充说，在 Docker 容器的帮助下，我们的注意力再次集中在应用上，而在 Oracle，我们将注意力放在如何让应用更好地运行在操作系统上。</p><p>“许多人过去常常需要繁琐地安装应用，而现在的年轻人只需要按一个按钮就能让应用在他们的移动设备上运行起来”。</p><p>人们对安装企业版的软件需要这么复杂的步骤而感到惊讶，而 Docker 帮助他们脱离了这片苦海。</p><p>“操作系统的角色已经变了。” Coekaerts 说。</p><p>Docker 的出现不代表虚拟机的淘汰，容器化过程需要经过很长时间才能变得成熟，然后才能在世界范围内得到应用。</p><p>在这段时间内，容器会与虚拟机共存，并且我们需要一些工具，将应用在容器和虚拟机之间进行转换迁移。Coekaerts 举例说 Oracle 的 VirtualBox 就可以用来帮助用户运行 Docker，而它原来是被广泛用在桌面系统上的一项开源技术。现在 Docker 的 Kitematic 项目将在 Mac 上使用 VirtualBox 运行 Docker。</p><h3 id="容器的开放计算计划和一次写随处部署" tabindex="-1">容器的开放计算计划和一次写随处部署 <a class="header-anchor" href="#容器的开放计算计划和一次写随处部署" aria-label="Permalink to “容器的开放计算计划和一次写随处部署”">​</a></h3><p>一个能让容器成功的关键是“一次写，随处部署”的概念。而在容器之间的互操作领域，Linux 基金会的开放计算计划（OCI）扮演一个非常关键的角色。</p><p>“使用 OCI，应用编译一次后就可以很方便地在多地运行，所以你可以将你的应用部署在任何地方”。</p><p>Coekaerts 总结说虽然在迁移到容器模型过程中会发生很多好玩的事情，但容器还没真正做好准备，他强调 Oracle 现在正在验证将产品运行在容器内的可行性，但这是一个非常艰难的过程。</p><p>“运行数据库很简单，难的是要搞定数据库所需的环境”，Coekaerts 说：“容器与虚拟机不一样，一些需要依赖底层系统配置的应用无法从主机迁移到容器中。”</p><p>另外，Coekaerts 指出在容器内调试问题与在虚拟机内调试问题也是不一样的，现在还没有成熟的工具来进行容器应用的调试。</p><p>Coekaerts 强调当容器足够成熟时，有一点很重要：不要抛弃现有的技术。组织和企业不能抛弃现有的部署好的应用，而完全投入新技术的怀抱。</p><p>“部署新技术是很困难的事情，你需要缓慢地迁移过去，能让你顺利迁移的技术才是成功的技术。”Coekaerts 说。</p><hr>',20)),a("p",null,[e[1]||(e[1]=t("via: ",-1)),o(r,{href:"http://www.serverwatch.com/server-news/linuxcon-the-changing-role-of-the-server-os.html"},{default:n(()=>[...e[0]||(e[0]=[t("http://www.serverwatch.com/server-news/linuxcon-the-changing-role-of-the-server-os.html",-1)])]),_:1})]),a("p",null,[e[5]||(e[5]=t("作者：",-1)),o(r,{href:"http://www.serverwatch.com/author/Sean-Michael-Kerner-101580.htm"},{default:n(()=>[...e[2]||(e[2]=[t("Sean Michael Kerner",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),o(r,{href:"https://github.com/bazz2"},{default:n(()=>[...e[3]||(e[3]=[t("bazz2",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=t("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创翻译，",-1)),o(r,{href:"https://linux.cn/"},{default:n(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const w=s(u,[["render",x]]);export{g as __pageData,w as default};
